import React from 'react'
import {StyleSheet, View} from 'react-native'
import {IconButton, TextInput} from 'react-native-paper'

import {
  useChatMessageInput,
  type ChatInputPropTypes,
} from '@features/chat/hooks/useChatMessageInput'
import COLORS from '@shared/constants/color'
import {MAX_CHAT_IMAGES} from '@shared/constants/chat'
import UploadButton from '@shared/ui/upload/UploadButton'

import ChatMentionSuggestion from './ChatMentionSuggestion'
import ImagePreview from './ImagePreview'

export default function ChatMessageInput({
  roomInfo,
  targetIds,
  chatType = 'group',
}: ChatInputPropTypes) {
  const {
    text,
    loading,
    selectedImage,
    setText,
    onSendMessage,
    isBlockRef,
    clearSelectedImage,
  } = useChatMessageInput({
    roomInfo,
    targetIds,
    chatType,
  })

  const selectedImages = selectedImage?.assets || []

  const removeImage = (uri: string) => {
    if (!selectedImage) return
    const nextAssets = selectedImage.assets?.filter(a => a.uri !== uri) || []
    if (nextAssets.length === 0) {
      clearSelectedImage()
    } else {
      // ImagePickerResponse structure 유지하면서 assets 필터링
      const nextResponse = {...selectedImage, assets: nextAssets}
      onSendMessage('image', nextResponse) // hook의 setSelectedImage를 업데이트하기 위해 onSendMessage('image', ...) 활용
    }
  }

  return (
    <>
      <View style={[styles.inputWrapper]}>
        <ChatMentionSuggestion
          text={text}
          setText={setText}
          disabled={loading}
          isBlockRef={isBlockRef}
        />

        <View style={[styles.inputContents]}>
          <UploadButton
            onChange={res => !loading && onSendMessage('image', res)}
            options={{quality: 0.5, selectionLimit: MAX_CHAT_IMAGES}}
            style={styles.uploadButton}
            disabled={loading}
          />
          <View style={styles.textInputContainer}>
            {selectedImages.length > 0 && (
              <View style={styles.previewList}>
                {selectedImages.map((asset, idx) => (
                  <ImagePreview
                    key={asset.uri || idx}
                    uri={asset.uri!}
                    onRemove={() => removeImage(asset.uri!)}
                  />
                ))}
              </View>
            )}
            <TextInput
              style={[styles.chatTextInput]}
              mode="outlined"
              contentStyle={styles.chatTextContent}
              outlineStyle={styles.chatTextOutlined}
              placeholder={
                selectedImages.length > 0 ? '사진에 대해 설명해주세요...' : ''
              }
              value={text}
              onChangeText={setText}
              multiline={true}
              dense={true}
              onSubmitEditing={() => !loading && onSendMessage('text')}
            />
          </View>
          <IconButton
            icon="send"
            size={25}
            style={styles.sendButton}
            iconColor={COLORS.onPrimary}
            onPress={() => !loading && onSendMessage('text')}
            loading={loading}
            disabled={loading}
          />
        </View>
      </View>
    </>
  )
}

const styles = StyleSheet.create({
  inputWrapper: {
    position: 'relative',
    backgroundColor: 'transparent',
    paddingBottom: 20,
    paddingHorizontal: 16,
  },
  inputContents: {
    backgroundColor: '#FFFFFF',
    borderRadius: 35,
    flexDirection: 'row',
    gap: 8,
    alignItems: 'flex-end', // 사진이 있을 때 버튼들을 아래로 정렬
    paddingVertical: 6,
    paddingHorizontal: 12,
    shadowColor: '#2D241F',
    shadowOffset: {width: 0, height: 10},
    shadowOpacity: 0.1,
    shadowRadius: 15,
    elevation: 8,
  },
  textInputContainer: {
    flex: 1,
  },
  previewList: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginTop: 8,
    marginBottom: 4,
  },
  chatTextInput: {
    backgroundColor: 'transparent',
    fontSize: 15,
    minHeight: 40,
    maxHeight: 120, // ✅ 최대 높이 다시 적용
  },
  chatTextContent: {
    paddingHorizontal: 12,
    paddingTop: 10,
    paddingBottom: 10,
    textAlignVertical: 'center',
    includeFontPadding: false,
    fontSize: 15,
  },
  chatTextOutlined: {
    borderRadius: 25,
    borderWidth: 0,
    backgroundColor: 'rgba(242, 114, 73, 0.05)',
  },
  uploadButton: {
    marginBottom: 10,
  },
  sendButton: {
    padding: 0,
    margin: 0,
    marginBottom: 4,
    width: 40,
    height: 40,
    borderRadius: 22,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: COLORS.primary,
    shadowColor: COLORS.primary,
    shadowOffset: {width: 0, height: 4},
    shadowOpacity: 0.3,
    shadowRadius: 6,
    elevation: 4,
  },
})
